def e_value_kappa_calibrator(p_values, alpha=0.1, kappa = 0.5):
    p_values = np.array(p_values)
    e_values = kappa * p_values ** (kappa-1)
    cum_e = np.prod(e_values)

    if cum_e > 1/alpha:
        return True, cum_e
    else:
        return False, cum_e
